import torch

from src.mythosmini.config import BLIMP_DATASET, BLIMP_PAIRS_PER_SUBTASK, EOS_TOKEN_ID
from src.mythosmini.benchmarks.scorer import ScoredPair, continuation_log_likelihoods
from src.mythosmini.model.transformer import MythosMini


def load_blimp_pairs(
    pairs_per_subtask: int = BLIMP_PAIRS_PER_SUBTASK,
) -> dict[str, list[tuple[str, str]]]:
    from datasets import get_dataset_config_names, load_dataset

    subtasks: dict[str, list[tuple[str, str]]] = {}
    for config_name in sorted(get_dataset_config_names(BLIMP_DATASET)):
        dataset = load_dataset(BLIMP_DATASET, name=config_name, split="train")
        pairs: list[tuple[str, str]] = []
        for record in dataset:
            pairs.append((str(record["sentence_good"]), str(record["sentence_bad"])))
            if len(pairs) >= pairs_per_subtask:
                break
        if pairs:
            subtasks[config_name] = pairs
    if not subtasks:
        raise ValueError(f"no blimp subtasks loaded from {BLIMP_DATASET}")
    return subtasks


def sentence_pair(sentence: str) -> ScoredPair:
    return ScoredPair(context=[EOS_TOKEN_ID], continuation=list(sentence.encode("utf-8")))


def blimp_accuracy(
    model: MythosMini,
    subtasks: dict[str, list[tuple[str, str]]],
    batch_size: int,
    device: str,
    dtype: torch.dtype,
) -> float:
    accuracies: list[float] = []
    for pairs in subtasks.values():
        scored: list[ScoredPair] = []
        for good, bad in pairs:
            scored.append(sentence_pair(good))
            scored.append(sentence_pair(bad))
        likelihoods = continuation_log_likelihoods(model, scored, batch_size, device, dtype)
        correct = sum(
            1 for index in range(len(pairs)) if likelihoods[2 * index] > likelihoods[2 * index + 1]
        )
        accuracies.append(correct / len(pairs))
    return 100.0 * sum(accuracies) / len(accuracies)
